export const renderPrecompiledRouteLoaders = entries => `export type GeneratedBaseReactFlowPrecompiledRouteDescriptor = {
  sourceHash: string;
  geometryDigest: string;
  load: () => Promise<unknown>;
};

/** Generated by scripts/generate-precompiled-display-routes.mjs. */
export const GENERATED_BASE_REACT_FLOW_PRECOMPILED_ROUTE_LOADERS: Record<
  string,
  GeneratedBaseReactFlowPrecompiledRouteDescriptor
> = {
${entries.map(entry => `  ${JSON.stringify(entry.inputSignature)}: {
    sourceHash: ${JSON.stringify(entry.sourceHash)},
    geometryDigest: ${JSON.stringify(entry.inputGeometryDigest)},
    load: () => import('./precompiledRoutes/${entry.artifactFile}').then(module => module.default),
  },`).join('\n')}
};
`;

export const renderPrecompiledRouteManifest = ({
  schema,
  routingVersion,
  identitySourceHash,
  entries,
}) => `${JSON.stringify({
  schema,
  routingVersion,
  identitySourceHash,
  entries,
}, null, 2)}\n`;

export const renderPrecompiledRouteArtifact = artifact => `${JSON.stringify(artifact, null, 2)}\n`;
